//! Native pattern validity connects actual edits, reporting, submission and paint.
use super::*;
struct Fixture(std::path::PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{(0..app.document.nodes.len()).find(|&n|app.document.attr(n,"id")==Some(id)).unwrap()}
fn click(app:&mut App,n:usize){let r=app.page.controls.iter().find(|r|r.node==n).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
#[test]
fn native_password_input_actual_app_edits_reporting_submit_recovery_paint_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-pattern-validation-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>input,button{display:block}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}#stable{position:absolute;left:420px;top:100px}</style><form id=form><input id=field type=password name=q pattern='(?i:😀ab)'><button id=send name=send>Submit</button></form><button id=go name=go type=button>Validate</button><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><div id=paint></div><div id=destination></div><script>var field=document.getElementById('field'),form=document.getElementById('form'),view=field.validity,round=0,inputs=0,invalid=0;field.addEventListener('input',function(e){if(!e.isTrusted)throw 'trusted edit';inputs++;if(view.patternMismatch!==(field.value!=='😀AB')||view.tooLong)throw 'flags before input listener';});field.addEventListener('invalid',function(e){if(!e.isTrusted||!view.patternMismatch||view.valid)throw 'trusted pattern invalid';invalid++;});form.addEventListener('submit',function(e){if(!e.isTrusted||e.submitter!==document.getElementById('send')||!view.valid||invalid!==2)throw 'trusted valid submission';e.preventDefault();document.title='Submitted';});document.getElementById('go').onclick=function(){if(field.validity!==view)throw 'stable view';if(round===0){if(view.patternMismatch||view.tooLong||!view.valid||!field.reportValidity())throw 'empty optional';document.title='Empty';field.focus();}else if(round===1){if(!view.patternMismatch||view.valid||field.validationMessage!=='Match the required pattern: q.'||field.reportValidity()!==false)throw 'native user mismatch';document.title='Mismatch';}else if(round===2){if(view.patternMismatch||!view.valid||!field.reportValidity()||inputs!==3)throw 'native repaired';document.getElementById('paint').className='done';document.title='Valid';}else{field.pattern='(?i:x)';field.value='X';if(view.patternMismatch||view.tooLong||!view.valid||!field.reportValidity())throw 'script pattern recovery';document.title='Script';}round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);
 let field=node(&app,"field");let go=node(&app,"go");let send=node(&app,"send");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let r=app.page.controls.iter().find(|r|r.node==field).unwrap();let rect=(r.x,r.y,r.width,r.height);app.forms.script_set_value(neighbor,"neighbor edit").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}
 let before=app.draw();click(&mut app,go);assert_eq!(app.document.title,"Empty");assert!(matches!(app.focus,Focus::Control(n)if n==field));app.text_input('😀');click(&mut app,go);assert_eq!(app.document.title,"Mismatch");assert!(app.failed);assert_eq!(app.status,"Match the required pattern: q.");click(&mut app,send);assert_eq!(app.document.title,"Mismatch");assert!(app.failed);assert_eq!(app.status,"Match the required pattern: q.");assert!(matches!(app.focus,Focus::Control(n)if n==field));app.text_input('A');app.text_input('B');click(&mut app,go);assert_eq!(app.document.title,"Valid");assert!(!app.failed&&app.status.is_empty());click(&mut app,send);assert_eq!(app.document.title,"Submitted");assert!(!app.failed&&!app.is_loading());click(&mut app,go);assert_eq!(app.document.title,"Script");assert!(!app.failed&&app.status.is_empty());assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());let painted=app.draw();let pixel=(app.content_top()+170)as usize*painted.width+430;assert_eq!(painted.pixels[pixel],0xcc2244);assert_ne!(before.pixels[pixel],painted.pixels[pixel]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("neighbor edit".into(),5,2,1));let r=app.page.controls.iter().find(|r|r.node==field).unwrap();assert_eq!((r.x,r.y,r.width,r.height),rect);assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw,location,epoch));
}

#[test]
fn native_password_input_masked_paint_geometry_and_clipboard(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-password-mask-{}.html",std::process::id())));
 std::fs::write(&file.0,"<!doctype html><style>input{font-family:Geometry;font-size:20px}</style><input id=field type=password size=4 value=AAAA><input id=plain value=iiii><a href=#next>Next</a><div id=next></div>").unwrap();
 let mut app=App::new();app.base_fonts.add("Geometry".into(),400,false,std::sync::Arc::new(crate::font::Font::parse(&crate::font::tests::fixture_font()).unwrap())).unwrap();app.fonts=app.base_fonts.clone();app.resize(640,480);app.open(&file.0);assert!(!app.failed);let field=node(&app,"field");let plain=node(&app,"plain");assert!(app.page.controls.iter().find(|r|r.node==field).unwrap().text_font.is_some());
 for bitmap in [false,true]{
  if bitmap{app.page.controls.iter_mut().find(|r|r.node==field).unwrap().text_font=None;}
  app.forms.script_set_value(field,"AAAA").unwrap();app.focus_control(field);app.sync_editors();let first=app.draw();
  let r=app.page.controls.iter().find(|r|r.node==field).unwrap();let(x,y)=(r.x+15,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);let first_cursor=app.forms.controls[&field].value.cursor;
  app.forms.script_set_value(field,"oooo").unwrap();app.sync_editors();let second=app.draw();
  app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.forms.controls[&field].value.cursor,first_cursor,"mask hit geometry");
  app.forms.script_set_value(field,"oooo").unwrap();app.sync_editors();app.key(0x23,false,false,false);let same_caret=app.draw();assert!(first.pixels==same_caret.pixels,"masked draw must not depend on plaintext, bitmap={bitmap}");let _=second;app.forms.script_set_value(field,"****").unwrap();app.sync_editors();assert!(first.pixels==app.draw().pixels,"exact mask glyph reference");app.forms.script_set_value(field,"oooo").unwrap();app.sync_editors();
  app.key(0x41,true,false,false);assert!(matches!(app.key(0x43,true,false,false),PlatformAction::None));assert!(matches!(app.key(0x58,true,false,false),PlatformAction::None));app.cut_copied("oooo");assert_eq!(app.forms.controls[&field].value.text(),"oooo");
 }
 app.focus_control(plain);app.key(0x41,true,false,false);assert!(matches!(app.key(0x43,true,false,false),PlatformAction::Copy(ref s)if s=="iiii"));
}
